def sha(b):return hashlib.sha256(b).hexdigest()
def canonical(r):return json.dumps(r,sort_keys=True,separators=(',',':')).encode()
def save(name,r):p=OUT/name;assert not p.exists();p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes((json.dumps(r,indent=2)+'\n').encode())
def md(name,text):p=OUT/name;assert not p.exists();p.write_bytes(text.encode())
def save_or_reference(name,r):
    old=HERE/name;data=(json.dumps(r,indent=2)+'\n').encode()
    if old.exists() and sha(old.read_bytes())==sha(data):save(name+'.reference.json',{'recomputed_exact_bytes':True,'artifact':old.relative_to(ROOT).as_posix(),'sha256':sha(data),'not_inherited_PASS':True})
    else:save(name,r)
def main():
    parser=Path(sys.argv[1]).resolve();git=lambda *a:subprocess.check_output(['git',*a],cwd=ROOT).decode().strip()
    assert git('branch','--show-current')=='checkpoint/package-0090-cloud-handoff' and git('rev-parse','HEAD')==git('rev-parse','origin/checkpoint/package-0090-cloud-handoff')==HEAD
    assert not git('diff','--name-only') and not git('diff','--cached','--name-only')
    inputs={p.relative_to(ROOT).as_posix():sha(p.read_bytes()) for p in HERE.iterdir() if p.is_file() and p.suffix=='.py'};save('IMMUTABLE-SOURCE.json',{'files':inputs,'sha256':sha(canonical(inputs))})
    data=typed_inventory.analyze(parser);save('PARSER-PROVENANCE.json',data['parser']);save('SQL-SOURCE-CATALOG.json',{'sources':data['sources'],'tables':data['tables'],'constraints_ast':data['constraints']})
    oracle=json.loads((ROOT/'docs/evidence/PACKAGE-0090-H02-INDEPENDENT-SQL-REVIEW.json').read_text())['public_contracts'];case_contract=json.loads((ROOT/'docs/evidence/package-0090-g3f4-full-domain-fixture-contract/POSITIVE-CASE-PRECONDITIONS.json').read_text())
    outgoing=collections.defaultdict(list)
