    summaries=[];reachable=set();roots={};unresolved=[]
    for key,contract in oracle.items():
        signature=contract['signature'].replace('pg_catalog.','').replace(' ','');assert signature in data['functions'],signature;roots[key]=signature
        visited=set();queue=[signature];pending=[]
