    save('EXTERNAL-WITNESS-MAP.json',{'frames':frame_map,'edges':edges['cross_layer_bindings'],'completion_receipt_fields':frames['receipt_payload_fields'],'independent_observer_graph':'HOST_PLATFORM -> HEALTH_GUARD -> seven managed participants; all required observations AND; no self-only acceptance','completion_source_rules':{'database':'Actual committed operation/receipt independently read back','census':'Successful catalog reconciliation and applicable snapshot/promotion registry CAS, not a pre-query tick','approval':'Original verified publication plus independently observed successful current generation consumption','terminate':'Retained target pidfd exit independently observed, not send ACK','cancel':'Actual query cancellation/outcome independently observed; UNKNOWN effects require reconciliation'},'status':'COMPLETE_DECLARED_DESIGN_MAPPING_NO_RUNTIME_VALIDATION'})
    prior=ROOT/'docs/evidence/package-0090-g3f4-sql-runtime-witness/final-02';controls=json.loads((prior/'PREDICATE-NEGATIVE-CONTROLS.json').read_text());frame_controls=json.loads((prior/'FRAME-WITNESS-REPLAY-MATRIX.json').read_text())
    assert len(controls)==514 and len(frame_controls)==235
    save('CONTROL-EVIDENCE-RECLASSIFICATION.json',{'controls':[{'prior_result':'PASS' if c['denied'] else 'FAIL','classification':'MODEL_ONLY_CONTROL','source':(prior/'PREDICATE-NEGATIVE-CONTROLS.json').relative_to(ROOT).as_posix(),'record':c} for c in controls],'frame_controls':[{'prior_result':'PASS' if c['denied'] else 'FAIL','classification':'RUNTIME_FRAME_MODEL_CONTROL','record':c} for c in frame_controls],'MODEL_ONLY_CONTROL_N':514,'LEXICAL_CONTROL_N':0,'TYPED_PREDICATE_CONTROL_N':0,'EXECUTABLE_SQL_CONTROL_N':0,'RUNTIME_FRAME_MODEL_CONTROL_N':235,'RUNTIME_EXECUTABLE_CONTROL_N':0,'scope':'The previous semantic/frame gate controls; no inherited executable SQL or native qualification. Older installation/native reports are preserved outside this denominator.'})
    fixture={'source_head':HEAD,'successor_sha256':typed_inventory.SUCCESSOR,'SQL_AUTHORITY_FIXTURE':{'binding_state':'MODEL_ONLY'},'EXTERNAL_RUNTIME_AUTHORITY_FIXTURE':None};assert not validate(fixture)['eligible'];fixture['EXTERNAL_RUNTIME_AUTHORITY_FIXTURE']={'producer_says_healthy':True};assert not validate(fixture)['eligible'];save('TWO-LAYER-VALIDATOR-REVIEW.json',{'sql_without_external_denied':True,'self_reported_external_with_sql_denied':True,'actual_positive_fixture_validation':'HOLD','positive_execution':False})
    stats=collections.Counter(p['PREDICATE_CLASS'] for p in predicates);typed=[p for p in predicates if p['boolean_type_inferred']=='bool' and not p['unresolved_type_or_binding']];join_n=sum(len({c['relation'] for c in p['column_bindings'] if c['relation']})>1 and p['OPERATOR'] in ['=','<>','<','>','<=','>='] for p in typed)
    metrics={'LEXICAL_CANDIDATE_N':14569,'TYPED_SQL_BOOLEAN_PREDICATE_N':len(typed),'TYPED_SQL_JOIN_PREDICATE_N':join_n,'TYPED_SQL_AUTHORITY_PREDICATE_N':stats['SQL_AUTHORITY_PREDICATE'],'TYPED_SQL_STATE_GUARD_N':stats['SQL_STATE_GUARD'],'TYPED_SQL_TIME_GUARD_N':stats['SQL_TIME_GUARD'],'TYPED_SQL_GENERATION_GUARD_N':stats['SQL_GENERATION_GUARD'],'TYPED_SQL_REVISION_GUARD_N':stats['SQL_REVISION_GUARD'],'TYPED_SQL_SCOPE_GUARD_N':stats['SQL_SCOPE_GUARD'],'NON_AUTHORITY_SQL_CONDITION_N':stats['NON_AUTHORITY_SQL_CONDITION'],'AST_BOOLEAN_NODE_CANDIDATE_N':len(predicates),'UNCLASSIFIED_PREDICATE_N':stats['UNCLASSIFIED'],'CLOSURE_DENOMINATOR_N':'UNKNOWN_INCOMPLETE_TYPED_CALL_CATALOG_CONTROL_FLOW_AND_IMPLICIT_DML_CLOSURE','SQL_AUTHORITY_EDGE_N':len(edges['sql_layer']),'EXTERNAL_AUTHORITY_EDGE_N':len(edges['external_layer']),'CROSS_LAYER_BINDING_EDGE_N':len(edges['cross_layer_bindings']),'UNCLASSIFIED_AUTHORITY_EDGE_N':0,'INVALID_OLD_MODEL_EDGE_N':len(edges['invalid_model_edges']),'UNRESOLVED_EXPLICIT_CALL_EDGE_N':len({sha(canonical(e)) for e in unresolved}),'reachable_sql_objects':len(reachable),'reachable_sql_statement_N':len(statements),'typed_counts_scope':'AST nodes with declared operand bindings/inferred bool; not PostgreSQL catalog/operator verification or closed authority denominator. Nested nodes retained as a tree; shared callee predicates counted once globally, with per-wrapper membership.'}
    save('TYPED-METRICS.json',metrics)
    # Pin all prior publication bytes, including the newest 67-file gate.
    sys.path.insert(0,str(ROOT/'scripts/validation/package_0090_executable_promotion'));spec=importlib.util.spec_from_file_location('historical',ROOT/'scripts/validation/package_0090_executable_promotion/final_gate.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);historical=m.preservation();assert not historical['failures'];history_n=historical['N']
    for rel in ['package-0090-g3f4-hash-bound-successor/final-02','package-0090-g3f4-full-domain-fixture-contract/final-01','package-0090-g3f4-sql-runtime-witness/final-02']:
        manifest=ROOT/'docs/evidence'/rel/'SHA256-PUBLICATION.json';old=json.loads(manifest.read_text());assert all(sha((ROOT/n).read_bytes())==h for n,h in old['files'].items());history_n+=len(old['files'])+1
    assert history_n==5331
    assert all(sha((ROOT/n).read_bytes())==h for n,h in inputs.items())
    report={**metrics,'EXTERNAL_AUTHORITY_BINDING_COMPLETE':'YES_DECLARED_DESIGN_NOT_RUNTIME_QUALIFIED','SQL_PREDICATE_COVERAGE_COMPLETE':'NO','AUTHORITY_JOIN_GRAPH_COMPLETE':'NO_SQL_ENFORCEMENT_MATCHES_AND_INVALID_MODELS_PENDING','EXTERNAL_AUTHORITY_WITNESS_MAP_COMPLETE':'YES_DESIGN_MAPPING_ONLY','COMPLETION_RECEIPT_FIELDS_COMPLETE':'YES_PUBLISHED_LOGICAL_DESIGN','COMPLETION_RECEIPT_EXTERNAL_CORROBORATION_COMPLETE':'YES_DESIGN_PATHS_NOT_EXECUTED','COMPLETION_RECEIPT_REPLAY_MODEL_COMPLETE':'YES_PRESERVED_LOGICAL_MODEL_SCOPE','COMPLETION_RECEIPT_RESTART_MODEL_COMPLETE':'YES_PRESERVED_LOGICAL_MODEL_SCOPE','MODEL_ONLY_CONTROL_N':514,'LEXICAL_CONTROL_N':0,'TYPED_PREDICATE_CONTROL_N':0,'EXECUTABLE_SQL_CONTROL_N':0,'RUNTIME_FRAME_MODEL_CONTROL_N':235,'RUNTIME_EXECUTABLE_CONTROL_N':0,'FIXTURE_SQL_AUTHORITY_COMPLETE':'NO','FIXTURE_EXTERNAL_AUTHORITY_COMPLETE':'NO_RUNTIME_WITNESSES_NOT_VALIDATED','FIXTURE_SCHEMA_COMPLETE':'NO_TYPED_SQL_WITNESS_SCHEMA_OPEN','POSITIVE_CASE_PRECONDITIONS_COMPLETE':'NO_TYPED_REACHABILITY_AND_ENFORCEMENT_GAPS','FULL_DOMAIN_FIXTURE_CONTRACT_READY':'NO','NATIVE_HEALTH_CONTRACT_READY':'YES_DESIGN_ONLY','MINIMAL_NATIVE_PROTOCOL_DELTA':'Unchanged: independently anchored producer/consumer/enforcement identities and replaceable slot generations, generation-bound externally corroborated completion receipt, independent one-use challenge/sequence ledger and pre-decision context CAS. No implementation.','NEW_AUTHORITY_REQUIRED':'YES_ONLY_FOR_FUTURE_NATIVE_OR_POSITIVE_EXECUTION_NOT_CURRENT_ANALYSIS','NATIVE_PROTOCOL_CHANGED':'NO','BLOCKER_COUNT':2,'HIGH_COUNT':1,'MEDIUM_COUNT':0,'LOW_COUNT':0,'FC01_STATUS':'HOLD_TYPED_SQL_AND_RUNTIME_WITNESS_VALIDATION','POSITIVE_WRAPPER_EXECUTION':'NO','input_head':HEAD,'source_sha256':sha(canonical(inputs)),'historical_checks':history_n,'historical_mismatch':0,'numeric_policy_adopted':False,'canonical_access_or_mutation':False,'new_runtime_resources':0,'owned_analysis_parser':str(parser),'analysis_parser_cleanup':'REQUIRED_AFTER_REVIEW','FAIL':0,'next_gate':'Resolve typed call/catalog bindings, exact predicate source spans and implicit DML dependencies; map actual SQL enforcement for corrected edges; validate both authority layers. Current design authority remains sufficient.'}
    save('FINAL-REVIEW.json',report)
    md('README.md','# SQL/external authority boundary and typed AST review\n\nHOLD. The former 14,569 lexical comparisons are diagnostic history only, never the closure denominator. Current counts come from PostgreSQL-family SQL and PL/pgSQL ASTs, declared parameter/table types and per-wrapper transitive call membership. Closure denominator is UNKNOWN because unresolved type/call/control-flow/source-span and implicit DML dependencies remain. No unclassified guard is silently converted into a non-authority condition.\n\nAll 40 old edges have one explicit boundary classification, including MODEL_ONLY_INVALID. Seven mismatches are reviewed individually. External/cryptographic/process/protocol edges have declared cross-layer witness bindings and no longer count as SQL mismatches. Invalid generic approval, receipt or reconciliation joins remain explicit correction findings; no fictional SQL relation is created.\n\nOnly analysis/evidence files changed. No SQL server, wrapper, native participant, signing key, canonical resource or production numeric policy was used.\n')
    md('METHOD-AND-LIMITATIONS.md','# Method and adversarial limitations\n\nParser API: [official pglast parser documentation](https://pglast.readthedocs.io/en/latest/parser.html); [official project](https://github.com/lelit/pglast). The isolated pinned parser reports v8.5 / PostgreSQL grammar 18.6; this is not PostgreSQL 18.4 execution proof. The temporary installation changes no repository dependencies. Parser extension hashes are recorded.\n\nThe analyzer loads immutable V001–V042 declarations to resolve only dependencies of the eighteen reviewed signatures used by the thirteen case paths. V043 is the exact accepted successor. Unrelated repository SQL never enters domain counts. Shared callees are counted once globally; wrapper membership is recorded separately. Unique arity selects explicit source call targets; ambiguous/missing targets remain unresolved rather than inferred. Implicit DML triggers/checks and overload/operator catalog verification remain pending and therefore prevent a closed denominator.\n\nASTs preserve AND/OR/NOT, NULL three-valued logic, EXISTS/subqueries and CASE. AST node categories and declared scalar types do not prove every PostgreSQL coercion/operator resolution. Exact SQL object ranges are retained; individual predicate spans are explicitly pending. Type/purpose failures remain UNCLASSIFIED. Only explicit CASE NULL discriminators are categorized non-authority; unsupported conditions are not dropped.\n\nThe offline PL compiler cannot resolve a table %ROWTYPE without a live catalog. Three proposed-record declarations are replaced with record only in a parser-only copy, then original field types are rebound from the immutable actual table declaration. Source predicates, original function hashes and bytes remain unchanged; the normalization is recorded and makes no runtime semantic-equivalence claim. No normalized copy is executed or promoted. Unqualified frozen declarations are catalogued in public, consistent with the reviewed installation boundary; live schema/catalog verification is still required.\n\nNo model/leaf/replay result becomes executable SQL or native proof. The 514 prior predicate-model and 235 frame-model PASS records remain preserved with their exact evidentiary scope. The two-layer design gate denies SQL-only fixtures and producer self-reported external health. Full SQL or external witness validation is not fabricated.\n')
    md('ADVERSARIAL-REVIEW.md','# Findings\n\nBLOCKER B01: typed source call/catalog/record/operator bindings, exact individual source spans and implicit DML constraint/trigger reachability are not fully closed; unclassified predicates and UNKNOWN denominator are retained. BLOCKER B02: independently acquired original frame/receipt/live SQL and external runtime witnesses are not validated by the design fixture gate. HIGH H01: invalid old generic approval/receipt/reconciliation edges require corrected typed enforcement witnesses; SQL column existence alone is not enforcement proof.\n\nCorrected: regex candidates removed from semantic denominator; actual AST grouping and NULL/NOT/EXISTS/subquery/CASE preserved; shared callee identity deduplicated; SQL and external authority separated; all seven mismatch decisions explicit; external bindings attach to exact header/runtime context rather than float freely; prior controls reclassified without overwriting PASS; no self-reported witness or protocol implementation introduced.\n\nNative health design remains unchanged. Completed work is a generation-bound externally corroborated receipt, not heartbeat freshness. Mandatory acyclic observation graph is HOST_PLATFORM -> HEALTH_GUARD -> seven managed participants. Unknown/stale context retains quarantine/ownership, denies promotion and requires reconciliation. SQL pointer generation is never equated with process/enrollment revision; reconciliation state is not observer-writable.\n')
